CREATE TABLE IF NOT EXISTS "ai_ppt" (
    "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "user_id" bigint NOT NULL,
    "title" varchar(255) NOT NULL DEFAULT '',
    "source" tinyint NOT NULL,
    "content" varchar(65535) DEFAULT NULL,
    "file_url" varchar(1024) DEFAULT NULL,
    "prompt" varchar(1024) NOT NULL DEFAULT '',
    "mode" tinyint NOT NULL,
    "language" varchar(16) NOT NULL DEFAULT 'zh-CN',
    "page_count" int NOT NULL,
    "chat_model_id" bigint NOT NULL,
    "image_model_id" bigint NOT NULL,
    "slides" varchar(65535) DEFAULT NULL,
    "cover_url" varchar(1024) DEFAULT NULL,
    "slide_count" int NOT NULL DEFAULT 0,
    "finish_count" int NOT NULL DEFAULT 0,
    "status" tinyint NOT NULL,
    "attempt" int NOT NULL DEFAULT 0,
    "error_message" varchar(1024) DEFAULT NULL,
    "finish_time" timestamp DEFAULT NULL,
    "creator" varchar(64) DEFAULT '',
    "create_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updater" varchar(64) DEFAULT '',
    "update_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "deleted" bit NOT NULL DEFAULT FALSE,
    "tenant_id" bigint NOT NULL DEFAULT 0,
    PRIMARY KEY ("id")
) COMMENT 'AI PPT 表';
